def show_pi_ai_source():
    """Best-effort source confirmation that pi-ai sends thinking blocks back to
    the model under the block's thinkingSignature (here 'reasoning_content').
    Tries several scopes and glob patterns and prints the matching file's lines
    around 'thinkingSignature'. Non-fatal if nothing resolves; the recorded
    traffic already carries the signature (event_samples.json)."""
    import glob
    base = pathlib.Path("/home/josiah/.local/share/fnm/node-versions/v22.20.0/installation/lib/node_modules")
    scope = base / "@earendil-works"
    patterns = ("**/openai-completions.js", "**/*openai*completions*.js",
                "**/*openai*.js", "**/*completions*.js")
    candidates, seen = [], set()
    for pat in patterns:
        if not scope.exists():
            break
        try:
            found = glob.glob(str(scope / pat), recursive=True)
        except Exception:
            continue
        for c in found:
            if c not in seen:
                seen.add(c)
                candidates.append(c)
    print("pi-ai openai-completions candidates:", candidates[:8])
    for f in candidates[:200]:
        try:
            raw = pathlib.Path(f).read_text(encoding="utf-8")
        except Exception:
            continue
        if "thinkingSignature" not in raw:
            continue
        lines = raw.splitlines()
        try:
            i = lines.index("thinkingSignature")
        except ValueError:
            continue
        print(f"--- {f}:{i + 1}")
        print("\n".join(lines[max(0, i - 16): i + 18]))
        return
    print("pi-ai source check: no file with 'thinkingSignature' under",
          scope)

